	case *ArrayPattern:
		var elements []Expr
		for _, e := range pat.Elements {
			lit := p.convertPatternToLiteral(e)
			if lit == nil {
				return nil
			}
			elements = append(elements, lit)
		}
		return &ArrayLit{
			LBrack:   pat.LBrack,
			Elements: elements,
			RBrack:   pat.RBrack,
