			}
			elements = append(elements, &MapElementLit{
				Key:    f.Key,
				KeyPos: f.KeyPos,
				Value:  lit,
			})
		}
		return &MapLit{
			LBrace:   pat.LBrace,
			Elements: elements,
			RBrace:   pat.RBrace,
		}
	case *DefaultExpr:
		p.error(pat.Pos(), "default value not allowed here")
		return nil
	case *RestExpr:
		p.error(pat.Pos(), "rest element not allowed here")
		return nil
	default:
		return pat
	}
}
